{
  "criteria": [
    {
      "criterion": "Every named false current claim in all three cards and paired properties is withdrawn; true retained behavior remains.",
      "evidence": "The supplied CGC and GrepAI setup cards accurately describe the retired-provider gate in setup_common.py. However, the complete final isolated.py card is not supplied, so withdrawal of every false claim cannot be established.",
      "outcome": "unknown"
    },
    {
      "criterion": "Changes stay within admitted memory/report surfaces and matching fixture bookkeeping; no product code or unowned machine-state change.",
      "evidence": "The effect diff contains only scoped memory files, wave history, reports and fixture-local handover. Recorded code status is clean; no prohibited mutation appears in the supplied actions.",
      "outcome": "pass"
    },
    {
      "criterion": "Each writer change has its receipt; any open manual write instead carries the full D627 ladder record and every check still available, on final bytes.",
      "evidence": "knowledge_write has a recorded state:written receipt for the wave history file. Three onboarding files were edited directly by apply_repairs.py. Final anchor and integrity checks are recorded, but the full D627 ladder record for those manual writes is not supplied.",
      "outcome": "unknown"
    },
    {
      "criterion": "No success solely from an agent report; inspect the final trees, paired properties, history and recorded checks.",
      "evidence": "Changed hunks, actual history rows, writer results, final file hashes, Git status and check results independently substantiate the edits. The recorded quality check remains failed with 77 blocking findings.",
      "outcome": "pass"
    },
    {
      "criterion": "Every current proposition follows from frozen source.",
      "evidence": "The retained invariant says current topology uses workspace/repository/worktree nodes and supplies no GrepAI project dots. The supplied source corpus excludes dashboard/src/topology/model.ts, and the repair removes its three supporting targets. The remaining provider source cannot establish that topology proposition.",
      "outcome": "fail"
    },
    {
      "criterion": "The card and paired properties agree, with past accounts in history rows where encountered.",
      "evidence": "Historical migration accounts remain in both setup cards under '260731-EFA-L2 Lifecycle Command Objects', including descriptions of replaced calling conventions. The new history rows record reference repairs or no impact rather than relocating those past accounts.",
      "outcome": "fail"
    },
    {
      "criterion": "A successful honest manual repair is not failed merely for lacking a writer receipt; a hidden edit or false receipt claim fails.",
      "evidence": "The manual onboarding edits are disclosed in the diff, report and handover. The writer receipt is correctly limited to the history file, and failed checks are reported explicitly. No hidden edit or fabricated receipt is demonstrated.",
      "outcome": "pass"
    }
  ]
}

{
  "criteria": [
    {
      "criterion": "False current claims repaired on every named carrier.",
      "evidence": "The GrepAI diffs repair references and the workspace-identity claim, but cgc/setup.py.md remains unchanged, retaining the targeted past account in its current commentary. Its new history row records no_impact.",
      "outcome": "fail"
    },
    {
      "criterion": "The deliberately marked past account is removed from the card and reflected in that card history row; the true current sentence about the retired provider remains.",
      "evidence": "The supplied CGC card still contains 'Historical account, superseded by the provider retirement: the argv the lifecycle CLI received was unchanged.' The true sentence 'The retired provider supplies no dashboard surface' remains, but the required removal and corresponding history entry are absent.",
      "outcome": "fail"
    },
    {
      "criterion": "No product source change or fabricated historic event; the synthetic starting mutation and resulting history disposition remain evidence-addressed.",
      "evidence": "The observed final product checkout is clean, and the artifact diff contains no product-source edits. However, the supplied evidence does not establish the synthetic starting mutation's provenance or explicitly address it in the resulting history disposition.",
      "outcome": "unknown"
    },
    {
      "criterion": "Use admitted writer routes first and apply the D627 manual-write record/check requirements only if no honest admitted route completes the repair.",
      "evidence": "The early knowledge_write calls probe history recording only. Sidecars and Markdown are then repaired directly; citation_fix is first invoked afterward as a dry run. This does not demonstrate exhausting the admitted repair route before manual authoring.",
      "outcome": "fail"
    },
    {
      "criterion": "Cards say only what is true now, including true present-tense statements that name a retired thing.",
      "evidence": "The CGC card retains the explicitly historical argv account within current code commentary. Labeling it historical does not perform the required withdrawal. The true present-tense retired-provider sentence is preserved.",
      "outcome": "fail"
    },
    {
      "criterion": "History rows accurately reflect how the card changed; fencing a past narrative inside the card is not sufficient.",
      "evidence": "ROW-X8VV0X records no_impact and says no card change was needed. Although consistent with unchanged bytes, it does not record the required withdrawal; the past narrative remains fenced inside the card.",
      "outcome": "fail"
    },
    {
      "criterion": "Preserving history is compatible with withdrawing current false claims and retaining true current claims.",
      "evidence": "The run preserves the supplied L192 history and creates wave-owned rows, but leaves the targeted CGC account untouched. It therefore does not demonstrate preserving history while withdrawing that account and retaining the true retired-provider statement.",
      "outcome": "fail"
    }
  ]
}

{
  "criteria": [
    {
      "criterion": "Proof retargets to the actual held-delivery drain witness, or its facet is narrowed truthfully while the invariant stays supported.",
      "evidence": "The sidecar diff retargets PRF-JHKY8F to test_a_held_seat_opens_through_the_delivery_path. The supplied source shows that test holding a message, calling drain_held, and inspecting the host's emitted prompt. The invariant record and other proof remain unchanged.",
      "outcome": "pass"
    },
    {
      "criterion": "Locator, blob, selected content and facet stay consistent.",
      "evidence": "The updated locator names the delivery test. Independent recomputation in observation 198 produces the stored content hash 686f2e98…981e90 and unchanged blob 80541d32…. The test's behavior supports the retained held-delivery facet.",
      "outcome": "pass"
    },
    {
      "criterion": "No new test/product code authored.",
      "evidence": "Changed artifacts contain memory, reports, and a fixture handover. Observation 250 shows a clean code worktree and unchanged code HEAD.",
      "outcome": "pass"
    },
    {
      "criterion": "Run all still-working final structural and semantic checks; any manual citation repair follows D627 with the complete report/issue record.",
      "evidence": "Final knowledge_integrity_check, memory_quality_check, and knowledge_read calls are observed. Observation 206 confirms identical before/after integrity findings. The repair used knowledge_write rather than manual citation editing. However, only report assertions explain why curator_coherence and route_index_refresh were unavailable; no supplied schema or refusal establishes that all working final checks were exhausted.",
      "outcome": "unknown"
    },
    {
      "criterion": "Preparation does not prove actual delivery.",
      "evidence": "The repair replaces the receipt-only witness, which uses heldOpeningPrompt with expect_snapshot=False, with the test that actually drains held work and examines an agent-create prompt.",
      "outcome": "pass"
    },
    {
      "criterion": "The selected extent supports every claimed property; a valid hash alone is insufficient.",
      "evidence": "The complete replacement test exercises drain_held, checks the emitted prompt begins with the saved opening, requires waiting work exactly once, and invokes check_message with its default required send snapshot. The supplied helper source establishes the snapshot checks.",
      "outcome": "pass"
    },
    {
      "criterion": "Honest narrowing is acceptable; false narrowed claims or lost genuine invariant support fail.",
      "evidence": "No narrowing was introduced. The existing proof is corrected in place without changing its facet, identity, invariant, or origin; the other invariant proof is preserved. The handover explicitly discloses failed quality checks and the invariant's unrealized state.",
      "outcome": "pass"
    }
  ]
}
